#!/usr/bin/env node
/**
 * Historical compliance-trade entry point — intentionally fail closed.
 *
 * A minimum-size order invented by this script would not be generated by Plumb's strategy,
 * cost, governor and reconciliation gates. Publishing prose beside it would not make it a valid
 * Plumb trade. The executable implementation was therefore removed before any live write.
 *
 * The replacement competition executor must consume a previously-finalised immutable
 * DecisionEvent that was delivered by the participating subscription service. Until that path is
 * complete, this command is a visible refusal rather than a loophole around eligibility.
 */

const execute = process.argv.includes('--execute');
const result = {
  ts: new Date().toISOString(),
  event: 'COMPLIANCE_TRADE_DISABLED',
  mode: execute ? 'EXECUTE_REFUSED' : 'DRY_RUN',
  blockers: [
    'no eligible strategy configuration exists',
    'no canonical approved DecisionEvent was supplied',
    'no matching A2A delivery acknowledgement exists',
    'a compliance-only trade would contradict the listed service gates',
  ],
  note: 'No order was placed. Build and approve the shared DecisionEvent path first.',
};

console.log(JSON.stringify(result));
process.exitCode = execute ? 1 : 0;
